    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "गन्तुं पावकमुन्मनस्तदभवद् दृष्ट्वा तु मित्रापदं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "युक्तं तेन जलेन शाम्यति सतां मैत्री पुनस्त्वीदृशी ॥७५॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "आत्मानं गतमात्मगतं यदुदकं तस्मै । गुणाः माधुर्यधावल्यादयः । उद्गृतं",
          "end": "space"
        },
        {
          "n": 2,
          "text": "मनो यस्य तदुन्मन उद्युक्तमित्यर्थः । उत्क उन्मना इति निपातनात्साधुः । ईदृशी",
          "end": "space"
        },
        {
          "n": 3,
          "text": "अन्योन्यव्यसनासहनशीलेत्यर्थः । अत्र स्वभावसिद्धस्य क्षीरनीरव्यवहारस्य पर-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "स्परसंतापदर्शनहेतुकत्वेनोत्प्रेक्षणात्क्रियानिमित्तक्रियास्वरूपोत्प्रेक्षा । सा चोक्तार्था-",
          "end": "hyphen"
        },
        {
          "n": 5,
          "text": "न्तरन्यासनिर्व्यूढेत्यनयोर्विजातीयसंकरः । इति रामचन्द्रबुधेन्द्रः । शार्दूल०",
          "end": "space"
        },
        {
          "n": 6,
          "text": "वृत्तम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "इतः स्वपिति केशवः कुलमितस्तदीयद्विषा-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "मितश्च शरणार्थिनः[१] शिखरिणां गणाः शेरते ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "",
          "end": "join"
        },
        {
          "n": 4,
          "text": "इतोपि वडवानलः सह समस्तसंवर्तकै-",
          "end": "hyphen"
        },
        {
          "n": 5,
          "text": "रहो विततमूर्जितं[२] भरसहं च सिन्धोर्वपुः[*] ॥ ७६ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "इत एकस्मिन्प्रदेशे इत्यर्थः । स्वपिति योगानुसंधानपरः शेते । रुदादिभ्यः",
          "end": "space"
        },
        {
          "n": 2,
          "text": "सार्वधातुके ( ७-२-७६ ) इतीडागमः । तस्य केशवस्येमे तदीयाः । त्यदादि-",
          "end": "hyphen"
        },
        {
          "n": 3,
          "text": "त्वाद्वृद्धाच्छः । तदीया द्विषो राक्षसाः तेषाम् । इतोन्यस्मिन्प्रदेशे । वडवानलो",
          "end": "space"
        },
        {
          "n": 4,
          "text": "वाडवाग्निः । और्वस्तु वाडवो वडवानलः इत्यमरः । संवर्तकाः प्रलयकालवर्षिणो",
          "end": "space"
        },
        {
          "n": 5,
          "text": "मेघविशेषास्तैः सह । अहो इत्याश्चर्ये । केशवशयनाधारतया विततं विस्तृतं वड-",
          "end": "hyphen"
        },
        {
          "n": 6,
          "text": "वानलाश्रयमपि वर्धिष्णुतयोर्जितं पर्वतभारोद्वहनाद्भरसहं च । अतोऽप्रमेयानुभा-",
          "end": "hyphen"
        },
        {
          "n": 7,
          "text": "वतया विस्मयावहमित्यर्थः । पृथ्वी वृत्तम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अथ सतां चेष्टितं वर्णयन् सदाचारं प्रदर्शयति—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "तृष्णां छिन्धि भज क्षमां जहि मदं पापे रतिं मा कृथाः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "सत्यं ब्रूह्यनुयाहि साधुपदवीं सेवस्व विद्वज्जनम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मान्यान्मानय विद्विषोप्यनुनय प्रच्छादय[३] स्वान्गुणा-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "न्कीर्तिं पालय दुःखिते कुरु दयामेतत्सतां लक्षणम्[४] ॥७७॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r9",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "छिन्धि वैराग्यशस्त्रेणेति भावः । सति क्रोधादिकारणे चित्तस्य निराकुलत्वं क्ष-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "मा ताम् । सेवस्व बुद्धिविकासार्थमिति भावः । तदुक्तं-यस्तु पर्यटते देशान्यस्तु",
          "end": "space"
        },
        {
          "n": 3,
          "text": "सेवेत पण्डितान् । तस्य विस्तारिता बुद्धिस्तैलविन्दुरिवाम्भसि ॥ मान्यान्पूज्या-",
          "end": "hyphen"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r10",
